begin;
select plan(14);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.enqueue_plan('00000000-0000-4000-8000-000000000101',now()+interval '1 day','00000000-0000-4000-8000-000000000501')$$,'23514',null,'readiness blocks premature rolling plan');
select lives_ok($$select public.set_planning_preferences('00000000-0000-4000-8000-000000000101',1,1,40,7)$$,'owner persists conservative cadence');
select public.approve_calendar('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',1);
select set_config('test.new_campaign',public.save_campaign('00000000-0000-4000-8000-000000000101',null,0,jsonb_build_object('title','Original synthetic sibling','goal','Approved facts only','planned_at',(select planned_at+interval '1 minute' from public.campaigns limit 1),'channel','email_design','audience_id','00000000-0000-4000-8000-000000000501','reference_notes',''))::text,true);
select throws_ok($$select public.approve_calendar('00000000-0000-4000-8000-000000000101',current_setting('test.new_campaign')::uuid,1)$$,'23514','Weekly cadence cap exceeded','weekly guard independent of generator');
select public.set_planning_preferences('00000000-0000-4000-8000-000000000101',1,5,40,7);
select public.approve_calendar('00000000-0000-4000-8000-000000000101',current_setting('test.new_campaign')::uuid,1);
select public.save_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',1,'{"subject":"50% off","preheader":"Synthetic","body":"Clinically proven through 2030-01-01.","cta":"Explore","url":"https://cedar-lane.example"}');
select is((select validation_state from public.campaign_content where campaign_id='00000000-0000-4000-8000-000000000601' and revision=2),'blocked','unverified claims persist as blocked copy');
select throws_ok($$select public.approve_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2)$$,'23514',null,'invalid copy cannot be approved');
select public.save_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2,'{"subject":"Original note","preheader":"Synthetic","body":"Explore at your own pace.","cta":"Explore","url":"https://cedar-lane.example"}');
select public.save_copy('00000000-0000-4000-8000-000000000101',current_setting('test.new_campaign')::uuid,1,'{"subject":"Original sibling","preheader":"Synthetic","body":"Explore the details.","cta":"Explore","url":"https://cedar-lane.example"}');
select set_config('test.batch',public.prepare_copy_review('00000000-0000-4000-8000-000000000101',(select planned_at::date from public.campaigns where id='00000000-0000-4000-8000-000000000601'))::text,true);
select public.save_copy('00000000-0000-4000-8000-000000000101',current_setting('test.new_campaign')::uuid,2,'{"subject":"Changed sibling","preheader":"Synthetic","body":"New exact wording.","cta":"Explore","url":"https://cedar-lane.example"}');
select throws_ok($$select public.approve_copy_batch('00000000-0000-4000-8000-000000000101',current_setting('test.batch')::uuid)$$,'PT409','Batch stale; no unseen version was approved','concurrent edit rejects whole batch');
select is((select count(*) from public.campaigns where copy_state='approved'),0::bigint,'stale batch rolls back all approvals');
select set_config('test.batch2',public.prepare_copy_review('00000000-0000-4000-8000-000000000101',(select planned_at::date from public.campaigns where id='00000000-0000-4000-8000-000000000601'))::text,true);
select is(public.approve_copy_batch('00000000-0000-4000-8000-000000000101',current_setting('test.batch2')::uuid),2,'current batch approved atomically');
select is(public.approve_copy_batch('00000000-0000-4000-8000-000000000101',current_setting('test.batch2')::uuid),2,'batch replay idempotent');
select public.reject_campaign_version('00000000-0000-4000-8000-000000000101',current_setting('test.new_campaign')::uuid,'copy',3,'Explicit synthetic prohibition','audience','Explore');
select is((select scope from public.owner_rules),'audience','rejection standing rule has explicit persisted scope');
select throws_ok($$select public.approve_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',3)$$,'23514',null,'standing prohibition checked on subsequent approval');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select throws_ok($$select public.prepare_copy_review('00000000-0000-4000-8000-000000000101',current_date)$$,'42501','Access denied','staff cannot prepare approval batch');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select is((select count(*) from public.copy_review_batches),0::bigint,'other tenant cannot inspect private reviews');
select is((select count(*) from public.owner_rules),0::bigint,'other tenant cannot inspect standing rules');
select * from finish();rollback;
